DECLARE c periodic_budget_controls%ROWTYPE;w periodic_budget_windows%ROWTYPE;observed_window text;
BEGIN
 IF extra IS NULL OR extra<0 THEN RAISE EXCEPTION 'periodic invalid extra' USING ERRCODE='23514';END IF;
 SELECT * INTO STRICT c FROM periodic_budget_controls WHERE id=control FOR NO KEY UPDATE;
 observed_window:=pb_observe(control,at_time);
 SELECT * INTO STRICT w FROM periodic_budget_windows WHERE id=observed_window AND control_id=c.id;
 IF c.enabled AND at_time>=c.effective_from AND w.spent_amount+c.held_amount+extra>c.limit_amount THEN
  RAISE EXCEPTION 'periodic budget exceeded' USING ERRCODE='23514',CONSTRAINT='pb_budget_'||c.scope;END IF;
END

DECLARE c periodic_budget_controls%ROWTYPE;start_time timestamptz;observed_window text;
BEGIN
 SELECT * INTO STRICT c FROM periodic_budget_controls WHERE id=control FOR NO KEY UPDATE;
 start_time:=pb_start(c.period_kind,at_time);
 IF start_time<c.max_observed_window_start OR at_time>pb_now() THEN RAISE EXCEPTION 'periodic clock regression' USING ERRCODE='23514';END IF;
 UPDATE periodic_budget_controls SET max_observed_window_start=start_time WHERE id=c.id;
 SELECT id INTO observed_window FROM periodic_budget_windows WHERE control_id=c.id AND start_at=start_time;
 IF observed_window IS NULL THEN observed_window:=gen_random_uuid()::text;
  INSERT INTO periodic_budget_windows(id,control_id,start_at,end_at) VALUES(observed_window,c.id,start_time,pb_end(c.period_kind,start_time));END IF;
 RETURN observed_window;
END

DECLARE c periodic_budget_controls%ROWTYPE;w periodic_budget_windows%ROWTYPE;window_view jsonb;current_state text;
BEGIN
 SELECT * INTO STRICT c FROM periodic_budget_controls WHERE id=control;
 IF pb_start(c.period_kind,at_time)<c.max_observed_window_start THEN RAISE EXCEPTION 'periodic clock regression' USING ERRCODE='23514';END IF;
 SELECT * INTO w FROM periodic_budget_windows WHERE control_id=c.id AND start_at=pb_start(c.period_kind,at_time);
 window_view:='null'::jsonb;
 IF w.id IS NOT NULL THEN window_view:=jsonb_build_object('id',w.id,'start_at',pricing_time(w.start_at),'end_at',pricing_time(w.end_at),
  'spent_amount',w.spent_amount::text,'held_amount',w.held_amount::text);END IF;
 IF c.held_amount<coalesce(w.held_amount,0) THEN RAISE EXCEPTION 'periodic negative carry' USING ERRCODE='23514'; END IF;
 current_state:=CASE WHEN NOT c.enabled THEN 'disabled' WHEN at_time<c.effective_from THEN 'scheduled' ELSE 'active' END;
 RETURN jsonb_build_object('scope',c.scope,'scope_id',coalesce(c.account_id,c.key_id,c.tenant_id),'revision',c.revision::text,
  'period_kind',c.period_kind,'enabled',c.enabled,'limit_amount',c.limit_amount::text,'state',current_state,
  'effective_from',pricing_time(c.effective_from),'tracking_started_at',pricing_time(c.tracking_started_at),
  'current_window',window_view,'carry_held',(c.held_amount-coalesce(w.held_amount,0))::text,'as_of',pricing_time(at_time));
END

DECLARE e alert_episodes; x alert_episode_events; n BIGINT; expected_n BIGINT; c alert_commands;
BEGIN
 SELECT * INTO e FROM alert_episodes WHERE id=p_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'event has no episode'; END IF;
 expected_n:=1+(e.acknowledged_at IS NOT NULL)::int+(e.resolved_at IS NOT NULL)::int;
 SELECT count(*) INTO n FROM alert_episode_events WHERE episode_id=e.id;
 IF n IS DISTINCT FROM expected_n THEN RAISE EXCEPTION 'incomplete episode history'; END IF;
 SELECT * INTO x FROM alert_episode_events WHERE episode_id=e.id AND action_revision=1;
 IF NOT FOUND OR (x.type,x.actor,x.observed_at,x.safe_sample,x.command_id)
   IS DISTINCT FROM ('opened'::text,'system'::text,e.opened_at,e.initial_sample,NULL::text) THEN RAISE EXCEPTION 'opened history mismatch'; END IF;
 IF e.acknowledged_at IS NOT NULL THEN
  SELECT * INTO x FROM alert_episode_events WHERE episode_id=e.id AND action_revision=2;
  IF NOT FOUND OR (x.type,x.actor,x.observed_at,x.safe_sample,x.command_id)
    IS DISTINCT FROM ('acknowledged'::text,e.acknowledged_by,e.acknowledged_at,NULL::jsonb,e.acknowledged_command_id) THEN RAISE EXCEPTION 'ack history mismatch'; END IF;
  SELECT * INTO c FROM alert_commands WHERE operation_id=e.acknowledged_command_id;
  IF NOT FOUND OR c.status<>'applied' OR c.kind<>'acknowledge' OR c.target_id IS DISTINCT FROM e.id
    OR c.resource_id IS DISTINCT FROM e.id OR c.actor IS DISTINCT FROM e.acknowledged_by OR c.result_revision<>2 THEN RAISE EXCEPTION 'ack receipt mismatch'; END IF;
 END IF;
 IF e.resolved_at IS NOT NULL THEN
  SELECT * INTO x FROM alert_episode_events WHERE episode_id=e.id AND action_revision=e.action_revision;
  IF NOT FOUND OR x.type IS DISTINCT FROM e.resolve_reason OR x.observed_at IS DISTINCT FROM e.resolved_at
    OR x.command_id IS DISTINCT FROM e.resolved_command_id THEN RAISE EXCEPTION 'resolve history mismatch'; END IF;
  IF e.resolve_reason='recovered' THEN
   IF x.actor IS DISTINCT FROM 'system' OR x.safe_sample IS DISTINCT FROM e.latest_sample THEN RAISE EXCEPTION 'recovery sample mismatch'; END IF;
  ELSE
   SELECT * INTO c FROM alert_commands WHERE operation_id=e.resolved_command_id;
   IF NOT FOUND OR c.status<>'applied' OR c.target_id IS DISTINCT FROM e.rule_id OR c.resource_id IS DISTINCT FROM e.rule_id
    OR c.kind IS DISTINCT FROM (CASE WHEN e.resolve_reason='rule_retired' THEN 'rule_retire' ELSE 'rule_configure' END)
    OR x.actor IS DISTINCT FROM c.actor OR x.safe_sample IS NOT NULL THEN RAISE EXCEPTION 'configuration event receipt mismatch'; END IF;
  END IF;
 END IF;
END

DECLARE r alert_rules; t alert_rule_runtime; e alert_episodes; max_generation BIGINT; c alert_commands;
BEGIN
 SELECT * INTO r FROM alert_rules WHERE id=p_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'missing alert rule'; END IF;
 SELECT * INTO t FROM alert_rule_runtime WHERE rule_id=p_id;
 IF NOT FOUND OR t.configured_revision IS DISTINCT FROM r.configuration_revision THEN RAISE EXCEPTION 'missing/stale runtime'; END IF;
 SELECT * INTO c FROM alert_commands WHERE operation_id=r.last_command_id;
 IF NOT FOUND OR c.status<>'applied' OR c.actor IS DISTINCT FROM r.updated_by OR c.resource_id IS DISTINCT FROM r.id
  OR c.result_revision IS DISTINCT FROM r.configuration_revision
  OR c.kind NOT IN ('rule_create','rule_configure','rule_retire') THEN RAISE EXCEPTION 'rule receipt mismatch'; END IF;
 SELECT generation INTO max_generation FROM alert_episodes WHERE rule_id=p_id ORDER BY generation DESC LIMIT 1;
 IF t.episode_generation IS DISTINCT FROM COALESCE(max_generation,0) THEN RAISE EXCEPTION 'generation mismatch'; END IF;
 SELECT * INTO e FROM alert_episodes WHERE rule_id=p_id AND resolved_at IS NULL;
 IF FOUND THEN
  IF t.current_episode_id IS DISTINCT FROM e.id OR e.rule_revision IS DISTINCT FROM r.configuration_revision OR r.state<>'enabled'
    OR t.last_sample IS DISTINCT FROM e.latest_sample OR t.last_success_at IS DISTINCT FROM e.last_seen_at THEN RAISE EXCEPTION 'active pointer/sample mismatch'; END IF;
 ELSE
  IF t.current_episode_id IS NOT NULL THEN RAISE EXCEPTION 'orphan current pointer'; END IF;
 END IF;
 IF r.state<>'enabled' AND t.next_evaluation_at IS NOT NULL THEN RAISE EXCEPTION 'inactive due time'; END IF;
 IF t.last_success_at IS NOT NULL THEN
  IF t.evaluated_revision IS DISTINCT FROM r.configuration_revision OR NOT alert_sample(t.last_sample,r.kind)
    OR t.last_success_at IS DISTINCT FROM (t.last_sample->>'as_of')::timestamptz THEN RAISE EXCEPTION 'runtime sample mismatch'; END IF;
  IF t.current_episode_id IS NULL AND alert_decision(jsonb_build_object('kind',r.kind,'scope_type',r.scope_type,'scope_id',r.scope_id,'label',r.label,'parameters',r.parameters),t.last_sample,false)='breach'
    THEN RAISE EXCEPTION 'breach has no episode'; END IF;
 END IF;
END

DECLARE n INTEGER; i INTEGER; cp INTEGER;
BEGIN
 IF v IS NULL THEN RETURN false; END IF;
 n:=char_length(v);
 IF n<1 OR n>80 OR octet_length(v)>160 THEN RETURN false; END IF;
 FOR i IN 1..n LOOP
  cp:=ascii(substr(v,i,1)); -- 受支持数据库编码必须UTF8，ascii返回Unicode code point
  IF cp BETWEEN 0 AND 31 OR cp BETWEEN 127 AND 159 THEN RETURN false; END IF;
  IF (i=1 OR i=n) AND (cp IN (32,133,160,5760,8232,8233,8239,8287,12288)
    OR cp BETWEEN 8192 AND 8202) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
END

BEGIN
 IF v IS NULL OR v !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{6}Z$' THEN RETURN false; END IF;
 RETURN to_char(v::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')=v;
EXCEPTION WHEN OTHERS THEN RETURN false;
END

DECLARE address CIDR; wire BYTEA; parts TEXT[] := '{}'; part INTEGER;
 current_start INTEGER := 0; current_length INTEGER := 0;
 best_start INTEGER := 0; best_length INTEGER := 0; position INTEGER; canonical TEXT;
BEGIN
 IF value IS NULL OR octet_length(value)>128 THEN RETURN NULL; END IF;
 address := value::CIDR;
 IF masklen(address)=0 THEN RETURN NULL; END IF;
 IF family(address)=4 THEN RETURN address::TEXT; END IF;
 wire := inet_send(address::INET);
 IF substring(wire FROM 5 FOR 12)=decode('00000000000000000000ffff','hex') THEN RETURN NULL; END IF;
 FOR position IN 0..7 LOOP
  part := get_byte(wire,4+position*2)*256+get_byte(wire,5+position*2);
  parts := array_append(parts,to_hex(part));
  IF part=0 THEN
   IF current_length=0 THEN current_start:=position+1; END IF;
   current_length:=current_length+1;
   IF current_length>best_length THEN best_start:=current_start; best_length:=current_length; END IF;
  ELSE current_length:=0;
  END IF;
 END LOOP;
 IF best_length>=2 THEN
  canonical := COALESCE(array_to_string(parts[1:best_start-1],':'),'') || '::' || COALESCE(array_to_string(parts[best_start+best_length:8],':'),'');
 ELSE canonical:=array_to_string(parts,':');
 END IF;
 RETURN canonical || '/' || masklen(address)::TEXT;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END

 DECLARE l funding_lots;b funding_lot_balances;last funding_lot_events; BEGIN
 SELECT * INTO STRICT l FROM funding_lots WHERE id=lid;
 IF EXISTS(
  WITH es AS (
   SELECT x.*,o.seq,row_number() OVER(ORDER BY o.seq) rn,lag(x.id) OVER(ORDER BY o.seq) prev,
    coalesce(sum(x.available_delta) OVER(ORDER BY o.seq ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) ba,
    coalesce(sum(x.inference_held_delta) OVER(ORDER BY o.seq ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) bh,
    coalesce(sum(x.consumed_delta) OVER(ORDER BY o.seq ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) bs
   FROM funding_lot_events x JOIN funding_wallet_operations o ON o.id=x.wallet_operation_id WHERE x.lot_id=lid
  ) SELECT 1 FROM es WHERE after_revision<>rn OR before_revision::numeric<>rn-1 OR previous_event_id IS DISTINCT FROM prev OR before_available::numeric<>ba OR before_held::numeric<>bh OR before_consumed::numeric<>bs
   OR after_available::numeric+after_held::numeric+after_consumed::numeric<>l.issued_amount::numeric OR issued_delta<>(CASE WHEN rn=1 THEN l.issued_amount::numeric ELSE 0 END)
 ) THEN RAISE EXCEPTION 'funding_lot_event_chain' USING ERRCODE='23514'; END IF;
 SELECT * INTO last FROM funding_lot_events WHERE lot_id=lid ORDER BY after_revision DESC LIMIT 1;SELECT * INTO b FROM funding_lot_balances WHERE lot_id=lid;
 IF last.id IS NULL OR b.lot_id IS NULL OR (b.tenant_id,b.revision,b.last_event_id,b.available_amount,b.inference_held_amount,b.consumed_amount) IS DISTINCT FROM (l.tenant_id,last.after_revision,last.id,last.after_available,last.after_held,last.after_consumed)
 THEN RAISE EXCEPTION 'funding_lot_balance_chain' USING ERRCODE='23514'; END IF;
 PERFORM fl_check_wallet_account(l.tenant_id);
END

 DECLARE f funding_receipts;l funding_lot_legacy_receipts;o text; BEGIN
 SELECT * INTO STRICT f FROM funding_receipts WHERE id=rid;
 IF f.source_kind='sandbox_capture' THEN PERFORM fl_check_sandbox_receipt(rid);RETURN; END IF;
 SELECT * INTO l FROM funding_lot_legacy_receipts WHERE receipt_id=rid;
 IF l.receipt_id IS NOT NULL THEN
  IF (l.tenant_id,l.source_kind,l.source_id,l.amount,l.journal_id) IS DISTINCT FROM (f.tenant_id,f.source_kind,f.source_id,f.amount,f.journal_id) OR EXISTS(SELECT 1 FROM funding_wallet_operations WHERE kind=f.source_kind AND source_id=rid) OR EXISTS(SELECT 1 FROM funding_lots WHERE funding_receipt_id=rid)
  THEN RAISE EXCEPTION 'funding_lot_legacy_receipt' USING ERRCODE='23514'; END IF;
  PERFORM fl_check_legacy_source(f.source_kind,rid);
 ELSE
  SELECT id INTO o FROM funding_wallet_operations WHERE kind=f.source_kind AND source_id=rid;
  IF o IS NULL THEN RAISE EXCEPTION 'funding_lot_missing_funding_operation' USING ERRCODE='23514'; END IF;
  PERFORM fl_check_wallet_operation(o);
 END IF;
END

 DECLARE f refund_orders;l funding_lot_legacy_approved_refunds;o text;k text; BEGIN
 SELECT * INTO STRICT f FROM refund_orders WHERE id=fid;
 IF f.state='pending' THEN
  IF f.journal_id IS NOT NULL OR f.approver IS NOT NULL OR EXISTS(SELECT 1 FROM funding_wallet_operations WHERE kind IN ('consumption_refund','legacy_consumption_refund') AND source_id=fid) OR EXISTS(SELECT 1 FROM funding_consumption_refund_lots WHERE refund_order_id=fid)
  THEN RAISE EXCEPTION 'funding_lot_pending_refund_effects' USING ERRCODE='23514'; END IF;RETURN;
 END IF;
 SELECT * INTO l FROM funding_lot_legacy_approved_refunds WHERE refund_order_id=fid;
 IF l.refund_order_id IS NOT NULL THEN
  IF (l.tenant_id,l.settlement_id,l.amount,l.journal_id) IS DISTINCT FROM (f.tenant_id,f.settlement_id,f.amount,f.journal_id) OR EXISTS(SELECT 1 FROM funding_consumption_refund_lots WHERE refund_order_id=fid) OR EXISTS(SELECT 1 FROM funding_lots WHERE legacy_refund_order_id=fid)
  THEN RAISE EXCEPTION 'funding_lot_legacy_approved_refund' USING ERRCODE='23514'; END IF;PERFORM fl_check_legacy_source('consumption_refund',fid);
 ELSE
  k:=CASE WHEN EXISTS(SELECT 1 FROM funding_lot_legacy_settlements WHERE settlement_id=f.settlement_id) THEN 'legacy_consumption_refund' ELSE 'consumption_refund' END;
  SELECT id INTO o FROM funding_wallet_operations WHERE kind=k AND source_id=fid;
  IF o IS NULL THEN RAISE EXCEPTION 'funding_lot_missing_refund_operation' USING ERRCODE='23514'; END IF;PERFORM fl_check_wallet_operation(o);
 END IF;
END

 DECLARE v reservations;o text;legacy boolean; BEGIN
 SELECT * INTO STRICT v FROM reservations WHERE id=rid;legacy:=EXISTS(SELECT 1 FROM funding_wallet_legacy_sources WHERE kind='reserve' AND source_id=rid);
 IF NOT EXISTS(SELECT 1 FROM request_records r WHERE r.id=v.request_id AND r.tenant_id=v.tenant_id AND r.billing_status=v.status) THEN RAISE EXCEPTION 'funding_lot_reservation_request_state' USING ERRCODE='23514'; END IF;
 IF legacy THEN
  PERFORM fl_check_legacy_source('reserve',rid);
  IF EXISTS(SELECT 1 FROM funding_lot_legacy_settlements WHERE reservation_id=rid) THEN
   IF EXISTS(SELECT 1 FROM funding_reservation_lots WHERE reservation_id=rid) THEN RAISE EXCEPTION 'funding_lot_historical_terminal_allocation' USING ERRCODE='23514'; END IF;
  ELSE
   SELECT id INTO o FROM funding_wallet_operations WHERE kind='epoch_opening' AND tenant_id=v.tenant_id;
   IF o IS NULL THEN RAISE EXCEPTION 'funding_lot_missing_opening_operation' USING ERRCODE='23514'; END IF;PERFORM fl_validate_genesis(o);
  END IF;
 ELSE
  SELECT id INTO o FROM funding_wallet_operations WHERE kind='reserve' AND source_id=rid;
  IF o IS NULL THEN RAISE EXCEPTION 'funding_lot_missing_reserve_operation' USING ERRCODE='23514'; END IF;PERFORM fl_check_wallet_operation(o);
 END IF;
 IF v.status IN ('reserved','pending_reconciliation') THEN
  IF EXISTS(SELECT 1 FROM settlements WHERE request_id=v.request_id) OR EXISTS(SELECT 1 FROM funding_settlement_lots b JOIN funding_reservation_lots a ON a.id=b.reservation_lot_id WHERE a.reservation_id=rid)
  THEN RAISE EXCEPTION 'funding_lot_unfinished_terminal_edges' USING ERRCODE='23514'; END IF;
 ELSE
  SELECT id INTO o FROM settlements WHERE request_id=v.request_id;
  IF o IS NULL THEN RAISE EXCEPTION 'funding_lot_missing_settlement_source' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM funding_lot_legacy_settlements WHERE settlement_id=o) THEN
   SELECT id INTO o FROM funding_wallet_operations WHERE kind='finish' AND source_id=o;
   IF o IS NULL THEN RAISE EXCEPTION 'funding_lot_missing_finish_operation' USING ERRCODE='23514'; END IF;PERFORM fl_check_wallet_operation(o);
  END IF;
 END IF;
END

 DECLARE f funding_receipts;l funding_lot_legacy_sandbox_receipts;o text; BEGIN
 SELECT * INTO STRICT f FROM funding_receipts WHERE id=rid AND source_kind='sandbox_capture';SELECT * INTO l FROM funding_lot_legacy_sandbox_receipts WHERE receipt_id=rid;
 IF l.receipt_id IS NOT NULL THEN
  IF (l.tenant_id,l.capture_id,l.amount,l.journal_id) IS DISTINCT FROM (f.tenant_id,f.source_id,f.amount,f.journal_id) OR EXISTS(SELECT 1 FROM funding_wallet_operations WHERE kind='sandbox_capture' AND source_id=rid) OR EXISTS(SELECT 1 FROM funding_lots WHERE funding_receipt_id=rid) OR NOT payment_sandbox_journal_valid(f.journal_id)
  THEN RAISE EXCEPTION 'funding_lot_sandbox_legacy_receipt' USING ERRCODE='23514'; END IF;
 ELSE
  SELECT id INTO o FROM funding_wallet_operations WHERE kind='sandbox_capture' AND source_id=rid;
  IF o IS NULL THEN RAISE EXCEPTION 'funding_lot_missing_sandbox_operation' USING ERRCODE='23514'; END IF;
  PERFORM fl_check_wallet_operation(o);
 END IF;
END

 DECLARE s settlements;l funding_lot_legacy_settlements;o text; BEGIN
 SELECT * INTO STRICT s FROM settlements WHERE id=sid;SELECT * INTO l FROM funding_lot_legacy_settlements WHERE settlement_id=sid;
 IF l.settlement_id IS NOT NULL THEN
  IF (l.tenant_id,l.request_id,l.charged_amount,l.journal_id) IS DISTINCT FROM (s.tenant_id,s.request_id,s.charged_amount,s.journal_id) OR s.refunded_amount<l.refunded_amount_at_cutover OR EXISTS(SELECT 1 FROM funding_settlement_lots WHERE settlement_id=sid)
  THEN RAISE EXCEPTION 'funding_lot_legacy_settlement' USING ERRCODE='23514'; END IF;
  PERFORM fl_check_legacy_source('finish',sid);
 ELSE
  SELECT id INTO o FROM funding_wallet_operations WHERE kind='finish' AND source_id=sid;
  IF o IS NULL THEN RAISE EXCEPTION 'funding_lot_missing_finish_operation' USING ERRCODE='23514'; END IF;PERFORM fl_check_wallet_operation(o);
 END IF;
END

 DECLARE a numeric;h numeric;la numeric;lh numeric; BEGIN
 SELECT coalesce(sum(balance::numeric) FILTER(WHERE kind='AVAILABLE'),0),coalesce(sum(balance::numeric) FILTER(WHERE kind='HELD'),0) INTO a,h FROM ledger_accounts WHERE tenant_id=t;
 SELECT coalesce(sum(available_amount::numeric),0),coalesce(sum(inference_held_amount::numeric),0) INTO la,lh FROM funding_lot_balances WHERE tenant_id=t;
 IF a<>la OR h<>lh THEN RAISE EXCEPTION 'funding_lot_wallet_balance' USING ERRCODE='23514'; END IF;
END

 DECLARE j journals;r text;o text; BEGIN
 SELECT * INTO STRICT j FROM journals WHERE id=jid;
 IF NOT EXISTS(SELECT 1 FROM journal_lines l JOIN ledger_accounts a ON a.id=l.account_id WHERE l.journal_id=jid AND a.kind IN ('AVAILABLE','HELD')) THEN RETURN; END IF;
 IF j.kind IN ('credit','voucher_grant','sandbox_capture') THEN
  SELECT id INTO r FROM funding_receipts WHERE journal_id=jid;
  IF r IS NULL THEN RAISE EXCEPTION 'funding_lot_orphan_funding_journal' USING ERRCODE='23514'; END IF;PERFORM fl_check_receipt(r);
 ELSIF j.kind='reserve' THEN
  SELECT id INTO r FROM reservations WHERE id=j.operation_id;
  IF r IS NULL THEN RAISE EXCEPTION 'funding_lot_orphan_reserve_journal' USING ERRCODE='23514'; END IF;PERFORM fl_check_reservation(r);
 ELSIF j.kind IN ('settled','released') THEN
  SELECT id INTO r FROM settlements WHERE journal_id=jid AND id=j.operation_id;
  IF r IS NULL THEN RAISE EXCEPTION 'funding_lot_orphan_finish_journal' USING ERRCODE='23514'; END IF;PERFORM fl_check_settlement(r);
 ELSIF j.kind='refund' THEN
  SELECT id INTO r FROM refund_orders WHERE journal_id=jid AND id=j.operation_id AND state='approved';
  IF r IS NULL THEN RAISE EXCEPTION 'funding_lot_orphan_refund_journal' USING ERRCODE='23514'; END IF;PERFORM fl_check_refund(r);
 ELSE RAISE EXCEPTION 'funding_lot_unknown_wallet_journal' USING ERRCODE='23514'; END IF;
END

 DECLARE o funding_wallet_operations;p fl_source_proof;e funding_lot_epoch;da numeric;dh numeric;ds numeric;di numeric; BEGIN
 SELECT * INTO STRICT o FROM funding_wallet_operations WHERE id=oid;e:=fl_require_epoch();
 IF o.epoch_id<>e.id THEN RAISE EXCEPTION 'funding_lot_operation_epoch' USING ERRCODE='23514'; END IF;
 IF o.kind IN ('epoch_opening','tenant_genesis') THEN PERFORM fl_validate_genesis(o.id);
 ELSE
  p:=fl_read_source(o.kind,o.source_id);
  IF (o.tenant_id,o.journal_id,o.journal_operation_id,o.available_delta,o.held_delta,o.consumed_delta,o.issued_delta) IS DISTINCT FROM (p.tenant_id,p.journal_id,p.journal_operation_id,p.available_delta,p.held_delta,p.consumed_delta,p.issued_delta)
  THEN RAISE EXCEPTION 'funding_lot_operation_source' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM journals j WHERE j.id=o.journal_id AND j.tenant_id=o.tenant_id AND j.created_txid::numeric=o.created_xid::text::numeric)
  THEN RAISE EXCEPTION 'funding_lot_operation_transaction' USING ERRCODE='23514'; END IF;
  IF o.kind='sandbox_capture' THEN PERFORM fl_validate_sandbox_funding(o.id);
  ELSIF o.kind IN ('manual_credit','voucher_grant') THEN PERFORM fl_validate_funding(o.id);
  ELSE
   IF EXISTS(SELECT 1 FROM funding_wallet_legacy_sources WHERE kind=CASE WHEN o.kind='legacy_consumption_refund' THEN 'consumption_refund' ELSE o.kind END AND source_id=o.source_id) THEN RAISE EXCEPTION 'funding_lot_operation_legacy_overlap' USING ERRCODE='23514'; END IF;
   IF o.kind='reserve' THEN PERFORM fl_validate_reserve(o.id);
   ELSIF o.kind='finish' THEN PERFORM fl_validate_finish(o.id);
   ELSIF o.kind='consumption_refund' THEN PERFORM fl_validate_refund(o.id);
   ELSIF o.kind='legacy_consumption_refund' THEN PERFORM fl_validate_legacy_refund(o.id);
   ELSE RAISE EXCEPTION 'funding_lot_operation_kind' USING ERRCODE='23514'; END IF;
  END IF;
 END IF;
 SELECT coalesce(sum(available_delta),0),coalesce(sum(inference_held_delta),0),coalesce(sum(consumed_delta),0),coalesce(sum(issued_delta),0) INTO da,dh,ds,di FROM funding_lot_events WHERE wallet_operation_id=o.id;
 IF o.event_count<>(SELECT count(*) FROM funding_lot_events WHERE wallet_operation_id=o.id) OR (o.available_delta,o.held_delta,o.consumed_delta,o.issued_delta) IS DISTINCT FROM (da,dh,ds,di)
 OR EXISTS(SELECT 1 FROM funding_lot_events x WHERE x.wallet_operation_id=o.id AND (x.tenant_id<>o.tenant_id OR x.wallet_seq<>o.seq OR x.journal_id IS DISTINCT FROM o.journal_id OR x.operation_id IS DISTINCT FROM o.journal_operation_id))
 THEN RAISE EXCEPTION 'funding_lot_operation_effects' USING ERRCODE='23514'; END IF;
 PERFORM fl_check_wallet_head(o.tenant_id);PERFORM fl_check_wallet_account(o.tenant_id);
END

 DECLARE f funding_receipts;j journals; BEGIN
 SELECT * INTO STRICT f FROM funding_receipts WHERE id=sid AND source_kind='manual_credit';
 SELECT * INTO STRICT j FROM journals WHERE id=f.journal_id;
 IF NOT payment_legacy_funding_journal_valid(j.id) OR NOT EXISTS(SELECT 1 FROM credit_orders c JOIN audit_events a ON a.target=c.id AND a.action='credit.approved' WHERE c.id=f.source_id AND a.tenant_scope=f.tenant_id AND a.actor=c.approver AND a.request_id='' AND a.sanitized_diff=jsonb_build_object('amount',f.amount::text))
 THEN RAISE EXCEPTION 'funding_lot_manual_source' USING ERRCODE='23514'; END IF;
 RETURN (f.tenant_id,j.id,j.operation_id,f.amount,f.amount::numeric,0,0,f.amount::numeric,f.created_at,'nonrefundable')::fl_source_proof;
END

 DECLARE v reservations;r request_records;j journals; BEGIN
 SELECT * INTO STRICT v FROM reservations WHERE id=sid;SELECT * INTO STRICT r FROM request_records WHERE id=v.request_id;
 SELECT * INTO STRICT j FROM journals WHERE operation_id=v.id;
 IF v.tenant_id<>r.tenant_id OR (j.tenant_id,j.kind,j.reference,j.actor,j.currency) IS DISTINCT FROM (v.tenant_id,'reserve',r.id,r.owner_id,'CNY') OR NOT fl_journal_lines(j.id,v.tenant_id,-v.amount::numeric,v.amount::numeric,0,false)
 OR NOT EXISTS(SELECT 1 FROM projection_outbox o WHERE o.operation_id=v.id AND o.kind='reserved' AND o.tenant_id=v.tenant_id AND o.schema_version=1 AND o.sanitized_payload=jsonb_build_object('amount',v.amount::text,'request_id',r.id))
 OR NOT EXISTS(SELECT 1 FROM audit_events a WHERE a.action='billing.reserve' AND a.target=j.id AND a.actor=r.owner_id AND a.tenant_scope=v.tenant_id AND a.request_id=r.id AND a.sanitized_diff=jsonb_build_object('amount',v.amount::text))
 THEN RAISE EXCEPTION 'funding_lot_reserve_source' USING ERRCODE='23514'; END IF;
 RETURN (v.tenant_id,j.id,j.operation_id,v.amount,-v.amount::numeric,v.amount::numeric,0,0,NULL,NULL)::fl_source_proof;
END

 DECLARE f funding_receipts;j journals; BEGIN
 SELECT * INTO STRICT f FROM funding_receipts WHERE id=sid AND source_kind='sandbox_capture';SELECT * INTO STRICT j FROM journals WHERE id=f.journal_id;
 IF NOT payment_sandbox_journal_valid(j.id) THEN RAISE EXCEPTION 'funding_lot_sandbox_source' USING ERRCODE='23514'; END IF;
 RETURN (f.tenant_id,j.id,j.operation_id,f.amount,f.amount::numeric,0,0,f.amount::numeric,f.created_at,'sandbox_original')::fl_source_proof;
END

 DECLARE f funding_receipts;j journals; BEGIN
 SELECT * INTO STRICT f FROM funding_receipts WHERE id=sid AND source_kind='voucher_grant';SELECT * INTO STRICT j FROM journals WHERE id=f.journal_id;
 IF NOT payment_legacy_funding_journal_valid(j.id) OR NOT EXISTS(SELECT 1 FROM voucher_redemptions r JOIN audit_events a ON a.target=r.id AND a.action='voucher.redeemed' WHERE r.funding_receipt_id=f.id AND a.tenant_scope=f.tenant_id AND a.actor=r.actor AND a.sanitized_diff=jsonb_build_object('amount',f.amount::text,'funding_receipt_id',f.id))
 THEN RAISE EXCEPTION 'funding_lot_voucher_source' USING ERRCODE='23514'; END IF;
 RETURN (f.tenant_id,j.id,j.operation_id,f.amount,f.amount::numeric,0,0,f.amount::numeric,f.created_at,'nonrefundable')::fl_source_proof;
END

 DECLARE o funding_wallet_operations;s settlements;v reservations; BEGIN
 SELECT * INTO STRICT o FROM funding_wallet_operations WHERE id=oid;SELECT * INTO STRICT s FROM settlements WHERE id=o.source_id;SELECT * INTO STRICT v FROM reservations WHERE request_id=s.request_id;
 IF EXISTS(SELECT 1 FROM funding_lot_legacy_settlements WHERE settlement_id=s.id) OR NOT EXISTS(SELECT 1 FROM funding_wallet_operations p WHERE p.tenant_id=o.tenant_id AND p.kind='reserve' AND p.source_id=v.id AND p.seq<o.seq)
  AND NOT EXISTS(SELECT 1 FROM funding_wallet_legacy_sources WHERE tenant_id=o.tenant_id AND kind='reserve' AND source_id=v.id)
 THEN RAISE EXCEPTION 'funding_lot_finish_boundary' USING ERRCODE='23514'; END IF;
 IF EXISTS(
  WITH alloc AS (SELECT a.*,coalesce(sum(amount::numeric) OVER(ORDER BY allocation_index ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) prior FROM funding_reservation_lots a WHERE reservation_id=v.id),
  expected AS (SELECT *,greatest(least(amount::numeric,s.charged_amount::numeric-prior),0) c FROM alloc),actual AS (SELECT * FROM funding_settlement_lots WHERE settlement_id=s.id)
  SELECT 1 FROM expected a FULL JOIN actual b ON b.reservation_lot_id=a.id WHERE a.id IS NULL OR b.id IS NULL OR b.tenant_id<>o.tenant_id OR b.charged_amount::numeric<>a.c OR b.released_amount::numeric<>a.amount::numeric-a.c
 ) OR (SELECT coalesce(sum(amount::numeric),0) FROM funding_reservation_lots WHERE reservation_id=v.id)<>v.amount::numeric
 OR EXISTS(
  WITH xs AS (SELECT a.lot_id,a.amount,b.charged_amount,b.released_amount FROM funding_settlement_lots b JOIN funding_reservation_lots a ON a.id=b.reservation_lot_id WHERE b.settlement_id=s.id),es AS (SELECT * FROM funding_lot_events WHERE wallet_operation_id=o.id)
  SELECT 1 FROM xs FULL JOIN es ON es.lot_id=xs.lot_id WHERE xs.lot_id IS NULL OR es.id IS NULL OR es.kind<>'finish' OR es.available_delta<>xs.released_amount::numeric OR es.inference_held_delta<>-xs.amount::numeric OR es.consumed_delta<>xs.charged_amount::numeric OR es.issued_delta<>0
 ) THEN RAISE EXCEPTION 'funding_lot_finish_allocation' USING ERRCODE='23514'; END IF;
END

 DECLARE o funding_wallet_operations; BEGIN
 SELECT * INTO STRICT o FROM funding_wallet_operations WHERE id=oid;
 IF o.kind NOT IN ('manual_credit','voucher_grant') OR EXISTS(SELECT 1 FROM funding_lot_legacy_receipts WHERE receipt_id=o.source_id) THEN RAISE EXCEPTION 'funding_lot_legacy_receipt_boundary' USING ERRCODE='23514'; END IF;
 PERFORM fl_validate_new_funding(oid);
END

 DECLARE o funding_wallet_operations;e funding_lot_epoch;birth xid8; BEGIN
 SELECT * INTO STRICT o FROM funding_wallet_operations WHERE id=oid;e:=fl_require_epoch();
 SELECT fl_created_xid INTO STRICT birth FROM tenants WHERE id=o.tenant_id;
 IF o.seq<>0 OR o.source_id<>o.tenant_id OR o.epoch_id<>e.id OR o.journal_id IS NOT NULL OR o.journal_operation_id IS NOT NULL THEN RAISE EXCEPTION 'funding_lot_genesis_identity' USING ERRCODE='23514'; END IF;
 IF o.kind='tenant_genesis' THEN
  IF birth IS NULL OR birth IS DISTINCT FROM o.created_xid OR EXISTS(SELECT 1 FROM funding_lot_legacy_openings WHERE tenant_id=o.tenant_id) OR o.event_count<>0 OR o.available_delta<>0 OR o.held_delta<>0 OR o.consumed_delta<>0 OR o.issued_delta<>0 OR EXISTS(SELECT 1 FROM funding_lot_events WHERE wallet_operation_id=o.id)
  THEN RAISE EXCEPTION 'funding_lot_tenant_genesis' USING ERRCODE='23514'; END IF;
 ELSIF o.kind='epoch_opening' THEN
  IF birth IS NOT NULL OR NOT EXISTS(SELECT 1 FROM funding_lot_legacy_openings WHERE tenant_id=o.tenant_id AND kind='available')
  OR EXISTS(
   WITH xs AS (SELECT * FROM funding_lot_legacy_openings WHERE tenant_id=o.tenant_id),ls AS (SELECT * FROM funding_lots WHERE tenant_id=o.tenant_id AND legacy_opening_id IS NOT NULL)
   SELECT 1 FROM xs FULL JOIN ls ON ls.legacy_opening_id=xs.id WHERE xs.id IS NULL OR (xs.amount=0 AND ls.id IS NOT NULL) OR (xs.amount>0 AND (ls.id IS NULL OR ls.issued_amount<>xs.amount OR ls.origin_kind<>'legacy_'||xs.kind)) OR xs.epoch_id<>e.id OR xs.observed_at<>e.created_at
  ) OR EXISTS(
   WITH xs AS (SELECT l.*,a.kind opening_kind FROM funding_lots l JOIN funding_lot_legacy_openings a ON a.id=l.legacy_opening_id WHERE a.tenant_id=o.tenant_id),es AS (SELECT * FROM funding_lot_events WHERE wallet_operation_id=o.id)
   SELECT 1 FROM xs FULL JOIN es ON es.lot_id=xs.id WHERE xs.id IS NULL OR es.id IS NULL OR xs.fifo_at<>e.created_at OR xs.refund_class<>'nonrefundable' OR es.kind<>'legacy_opening' OR es.before_revision<>0 OR es.before_available<>0 OR es.before_held<>0 OR es.before_consumed<>0 OR es.consumed_delta<>0 OR es.issued_delta<>xs.issued_amount::numeric
    OR es.available_delta<>(CASE WHEN xs.opening_kind='available' THEN xs.issued_amount::numeric ELSE 0 END) OR es.inference_held_delta<>(CASE WHEN xs.opening_kind='reservation' THEN xs.issued_amount::numeric ELSE 0 END)
  ) OR EXISTS(
   WITH xs AS (SELECT a.*,l.id lot_id FROM funding_lot_legacy_openings a LEFT JOIN funding_lots l ON l.legacy_opening_id=a.id WHERE a.tenant_id=o.tenant_id AND a.kind='reservation'),rs AS (SELECT r.* FROM funding_reservation_lots r JOIN funding_wallet_legacy_sources s ON s.kind='reserve' AND s.source_id=r.reservation_id WHERE s.tenant_id=o.tenant_id)
   SELECT 1 FROM xs FULL JOIN rs ON rs.reservation_id=xs.reservation_id WHERE xs.id IS NULL OR (xs.amount=0 AND rs.id IS NOT NULL) OR (xs.amount>0 AND (rs.id IS NULL OR rs.lot_id<>xs.lot_id OR rs.amount<>xs.amount OR rs.allocation_index<>1 OR rs.tenant_id<>o.tenant_id))
  ) THEN RAISE EXCEPTION 'funding_lot_epoch_genesis' USING ERRCODE='23514'; END IF;
 ELSE RAISE EXCEPTION 'funding_lot_genesis_kind' USING ERRCODE='23514'; END IF;
END

 DECLARE o funding_wallet_operations;p fl_source_proof; BEGIN
 SELECT * INTO STRICT o FROM funding_wallet_operations WHERE id=oid;p:=fl_read_source(o.kind,o.source_id);
 IF (SELECT count(*) FROM funding_lots WHERE funding_receipt_id=o.source_id)<>1
 OR EXISTS(
  WITH ls AS (SELECT * FROM funding_lots WHERE funding_receipt_id=o.source_id),es AS (SELECT * FROM funding_lot_events WHERE wallet_operation_id=o.id)
  SELECT 1 FROM ls FULL JOIN es ON es.lot_id=ls.id WHERE ls.id IS NULL OR es.id IS NULL OR ls.tenant_id<>p.tenant_id OR ls.origin_kind<>'funding_receipt' OR ls.issued_amount<>p.amount OR ls.fifo_at<>p.fifo_at OR ls.refund_class<>p.refund_class OR es.kind<>'funding'
   OR es.before_revision<>0 OR es.before_available<>0 OR es.before_held<>0 OR es.before_consumed<>0 OR es.available_delta<>p.amount::numeric OR es.inference_held_delta<>0 OR es.consumed_delta<>0 OR es.issued_delta<>p.amount::numeric
 ) THEN RAISE EXCEPTION 'funding_lot_funding_mapping' USING ERRCODE='23514'; END IF;
END

 DECLARE o funding_wallet_operations;f refund_orders; BEGIN
 SELECT * INTO STRICT o FROM funding_wallet_operations WHERE id=oid;SELECT * INTO STRICT f FROM refund_orders WHERE id=o.source_id AND state='approved';
 IF EXISTS(SELECT 1 FROM funding_lot_legacy_settlements WHERE settlement_id=f.settlement_id) OR EXISTS(SELECT 1 FROM funding_lot_legacy_approved_refunds WHERE refund_order_id=f.id)
 OR NOT EXISTS(SELECT 1 FROM funding_wallet_operations p WHERE p.tenant_id=o.tenant_id AND p.kind='finish' AND p.source_id=f.settlement_id AND p.seq<o.seq)
 THEN RAISE EXCEPTION 'funding_lot_refund_boundary' USING ERRCODE='23514'; END IF;
 IF EXISTS(
  WITH edges AS (
   SELECT b.id,a.allocation_index,b.charged_amount::numeric-coalesce((SELECT sum(r.amount::numeric) FROM funding_consumption_refund_lots r JOIN funding_wallet_operations p ON p.kind='consumption_refund' AND p.source_id=r.refund_order_id WHERE r.settlement_lot_id=b.id AND p.tenant_id=o.tenant_id AND p.seq<o.seq),0) remain
   FROM funding_settlement_lots b JOIN funding_reservation_lots a ON a.id=b.reservation_lot_id WHERE b.settlement_id=f.settlement_id
  ),candidates AS (SELECT *,coalesce(sum(remain) OVER(ORDER BY allocation_index DESC ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) prior FROM edges WHERE remain>0),
  expected0 AS (SELECT *,greatest(least(remain,f.amount::numeric-prior),0) q FROM candidates),expected AS (SELECT *,row_number() OVER(ORDER BY allocation_index DESC) idx FROM expected0 WHERE q>0),actual AS (SELECT * FROM funding_consumption_refund_lots WHERE refund_order_id=f.id)
  SELECT 1 FROM expected x FULL JOIN actual a ON a.settlement_lot_id=x.id WHERE x.id IS NULL OR a.id IS NULL OR a.tenant_id<>o.tenant_id OR a.origin<>'allocated' OR a.amount::numeric<>x.q OR a.allocation_index<>x.idx
 ) OR (SELECT coalesce(sum(amount::numeric),0) FROM funding_consumption_refund_lots WHERE refund_order_id=f.id)<>f.amount::numeric
 OR EXISTS(
  WITH xs AS (SELECT r.lot_id,r.amount FROM funding_consumption_refund_lots r WHERE r.refund_order_id=f.id),es AS (SELECT * FROM funding_lot_events WHERE wallet_operation_id=o.id)
  SELECT 1 FROM xs FULL JOIN es ON es.lot_id=xs.lot_id WHERE xs.lot_id IS NULL OR es.id IS NULL OR es.kind<>'consumption_refund' OR es.available_delta<>xs.amount::numeric OR es.inference_held_delta<>0 OR es.consumed_delta<>-xs.amount::numeric OR es.issued_delta<>0
 ) THEN RAISE EXCEPTION 'funding_lot_reverse_refund' USING ERRCODE='23514'; END IF;
END

 DECLARE o funding_wallet_operations; BEGIN
 SELECT * INTO STRICT o FROM funding_wallet_operations WHERE id=oid;
 IF o.kind<>'sandbox_capture' OR EXISTS(SELECT 1 FROM funding_lot_legacy_sandbox_receipts WHERE receipt_id=o.source_id) THEN RAISE EXCEPTION 'funding_lot_sandbox_legacy_boundary' USING ERRCODE='23514'; END IF;
 PERFORM fl_validate_new_funding(oid);
END

BEGIN
 -- Use a statement-level branch: the worker must not need SELECT on A's
 -- voucher/manual source tables just to validate its sandbox journal.
 IF EXISTS(SELECT 1 FROM journals WHERE id=journal_ref AND kind='sandbox_capture') THEN RETURN payment_sandbox_journal_valid(journal_ref);END IF;
 RETURN payment_legacy_funding_journal_valid(journal_ref);
END

DECLARE e payment_verified_evidence%ROWTYPE;o payment_orders%ROWTYPE;m payment_sandbox_environment%ROWTYPE;
 original jsonb;request jsonb;fact jsonb;received timestamptz;event_ref text;
 a payment_query_attempts%ROWTYPE;s payment_command_outbox%ROWTYPE;c payment_command_outbox%ROWTYPE;
BEGIN
 SELECT * INTO e FROM payment_verified_evidence WHERE id=evidence_ref;
 IF NOT FOUND OR e.kind<>'capture' THEN RETURN false;END IF;
 SELECT * INTO o FROM payment_orders WHERE id=e.order_id;IF NOT FOUND THEN RETURN false;END IF;
 SELECT * INTO m FROM payment_sandbox_environment WHERE singleton;IF NOT FOUND THEN RETURN false;END IF;
 IF m.database_oid<>(SELECT oid FROM pg_database WHERE datname=current_database()) OR m.schema_oid<>current_schema()::regnamespace::oid
  OR (e.environment_id,e.merchant_id) IS DISTINCT FROM (m.id,m.merchant_id)
  OR (e.environment_id,e.merchant_id,e.order_id,e.amount,e.currency) IS DISTINCT FROM (o.environment_id,o.merchant_id,o.id,o.amount,o.currency)
 THEN RETURN false;END IF;
 IF e.inbox_id IS NOT NULL AND e.verified_query_id IS NULL THEN
  SELECT convert_from(canonical_body,'UTF8')::jsonb,received_at,event_id INTO original,received,event_ref
   FROM payment_inbox WHERE id=e.inbox_id AND (environment_id,merchant_id)=(e.environment_id,e.merchant_id);
  IF NOT FOUND OR original->'schema_version' IS DISTINCT FROM '1'::jsonb OR original->>'event_type' IS DISTINCT FROM 'capture.confirmed'
   OR (original->>'environment_id',original->>'merchant_id',original->>'order_id',original->>'event_id') IS DISTINCT FROM (e.environment_id,e.merchant_id,e.order_id,event_ref)
  THEN RETURN false;END IF;
  fact:=original;
 ELSIF e.inbox_id IS NULL AND e.verified_query_id IS NOT NULL THEN
  SELECT convert_from(v.canonical_body,'UTF8')::jsonb,v.received_at,v.query_id INTO original,received,event_ref FROM payment_verified_queries v WHERE v.id=e.verified_query_id;
  IF NOT FOUND THEN RETURN false;END IF;
  SELECT * INTO a FROM payment_query_attempts WHERE query_id=event_ref;IF NOT FOUND THEN RETURN false;END IF;
  SELECT * INTO s FROM payment_command_outbox WHERE id=a.supervisor_id;IF NOT FOUND OR s.kind<>'query' THEN RETURN false;END IF;
  SELECT * INTO c FROM payment_command_outbox WHERE id=s.original_outbox_id;IF NOT FOUND OR c.kind NOT IN ('checkout','cancel') OR c.order_id<>e.order_id OR s.order_id<>e.order_id THEN RETURN false;END IF;
  request:=convert_from(a.canonical_request,'UTF8')::jsonb;
  IF request->'schema_version' IS DISTINCT FROM '1'::jsonb OR original->'schema_version' IS DISTINCT FROM '1'::jsonb
   OR (request->>'query_id',request->>'environment_id',request->>'merchant_id',request->>'merchant_order_id',request->>'command_id',request->>'command_kind',request->>'parameter_digest')
    IS DISTINCT FROM (a.query_id,o.environment_id,o.merchant_id,o.merchant_order_id,c.external_command_id,c.kind,c.parameter_digest)
   OR (original->>'query_id',original->>'environment_id',original->>'merchant_id',original->>'merchant_order_id',original->>'command_id',original->>'command_kind',original->>'parameter_digest')
    IS DISTINCT FROM (request->>'query_id',request->>'environment_id',request->>'merchant_id',request->>'merchant_order_id',request->>'command_id',request->>'command_kind',request->>'parameter_digest')
   OR a.created_generation<1 OR a.created_generation>s.generation OR a.mutation_generation<1 OR a.mutation_generation>c.generation
   OR a.request_digest<>encode(sha256(a.canonical_request),'hex') OR c.parameter_digest<>encode(sha256(c.canonical_parameters),'hex')
   OR original->>'command_state' IS DISTINCT FROM 'completed' OR original->'result'->>'status' IS DISTINCT FROM 'captured'
  THEN RETURN false;END IF;
  fact:=original->'result'->'capture';
  IF fact->>'provider_order_revision' IS DISTINCT FROM original->>'provider_order_revision' THEN RETURN false;END IF;
 ELSE RETURN false;END IF;
 RETURN coalesce((fact->>'provider_transaction_id',fact->>'amount',fact->>'currency',fact->>'occurred_at',fact->>'provider_order_revision')
   IS NOT DISTINCT FROM (e.provider_transaction_id,e.amount::text,e.currency,payment_time(e.happened_at),e.provider_order_revision::text)
  AND e.verified_at=received AND e.happened_at<=received+interval '5 seconds'
  AND e.fact_digest=encode(sha256(payment_frame(ARRAY[e.environment_id,e.merchant_id,e.order_id,'capture',e.provider_transaction_id,e.amount::text,e.currency,payment_time(e.happened_at),e.provider_order_revision::text])),'hex'),false);
EXCEPTION WHEN data_exception THEN RETURN false;
END

DECLARE c commerce_commands%ROWTYPE;r commerce_operation_receipts%ROWTYPE;valid boolean:=false;
BEGIN
 SELECT * INTO STRICT c FROM commerce_commands WHERE operation_id=operation_ref;
 IF c.kind NOT LIKE 'payment.%' THEN RETURN;END IF;
 SELECT * INTO STRICT r FROM commerce_operation_receipts WHERE operation_id=c.operation_id;
 IF r.status='rejected' THEN
  IF (c.kind IN ('payment.sku.publish','payment.sku.activate') AND r.reason NOT IN ('payment_revision_conflict','payment_state_conflict')) OR
   (c.kind='payment.order.create' AND r.reason NOT IN ('payments_disabled','payment_sku_unavailable')) OR
   (c.kind='payment.order.cancel' AND r.reason<>'payment_state_conflict') THEN RAISE EXCEPTION 'payment terminal reason invalid';END IF;
  IF EXISTS(SELECT 1 FROM payment_sku_changes WHERE operation_id=c.operation_id) OR EXISTS(SELECT 1 FROM payment_sku_versions WHERE publish_operation_id=c.operation_id) OR
   EXISTS(SELECT 1 FROM payment_orders WHERE id=c.operation_id) OR EXISTS(SELECT 1 FROM payment_cancel_intents WHERE operation_id=c.operation_id) OR EXISTS(SELECT 1 FROM audit_events WHERE action=c.kind AND target=c.operation_id) THEN RAISE EXCEPTION 'rejected payment command has effect';END IF;RETURN;
 END IF;
 IF c.kind='payment.sku.publish' THEN
  SELECT EXISTS(SELECT 1 FROM payment_sku_versions v JOIN payment_sku_changes x ON x.published_version_id=v.id WHERE v.id=r.resource_id AND v.publish_operation_id=c.operation_id AND v.created_by=c.actor AND x.operation_id=c.operation_id AND x.sku_id=v.sku_id AND x.kind=c.kind) INTO valid;
 ELSIF c.kind='payment.sku.activate' THEN
  SELECT EXISTS(SELECT 1 FROM payment_sku_changes x WHERE x.operation_id=c.operation_id AND x.sku_id=r.resource_id AND x.kind=c.kind) INTO valid;
 ELSIF c.kind='payment.order.create' THEN
  SELECT EXISTS(SELECT 1 FROM payment_orders o JOIN payment_command_outbox b ON b.order_id=o.id AND b.kind='checkout' WHERE o.id=c.operation_id AND o.id=r.resource_id AND o.creator=c.actor AND c.scope='tenant:'||o.tenant_id) INTO valid;
 ELSE
  SELECT EXISTS(SELECT 1 FROM payment_cancel_intents x JOIN payment_orders o ON o.id=x.order_id JOIN payment_command_outbox b ON b.order_id=o.id AND b.kind='cancel' WHERE x.operation_id=c.operation_id AND x.order_id=r.resource_id AND x.actor=c.actor AND c.scope='tenant:'||o.tenant_id) INTO valid;
 END IF;
 IF NOT valid OR NOT EXISTS(SELECT 1 FROM audit_events WHERE action=c.kind AND target=c.operation_id AND actor=c.actor AND tenant_scope IS NOT DISTINCT FROM (CASE WHEN c.scope='platform' THEN NULL ELSE substr(c.scope,8) END) AND sanitized_diff='{}'::jsonb) THEN RAISE EXCEPTION 'payment command resource incomplete' USING ERRCODE='23514';END IF;
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION 'payment command terminal missing' USING ERRCODE='23514';
END

DECLARE r request_records%ROWTYPE;v reservations%ROWTYPE;c periodic_budget_controls%ROWTYPE;
 a periodic_budget_allocations%ROWTYPE;s settlements%ROWTYPE;expected_h numeric;expected_s numeric;expected_state text;marker text;
BEGIN
 SELECT * INTO r FROM request_records WHERE id=subject;IF NOT FOUND THEN RETURN;END IF;
 SELECT * INTO v FROM reservations WHERE request_id=r.id;IF NOT FOUND THEN
  IF r.pb_created_xid IS NOT NULL OR r.pb_tenant_control IS NOT NULL OR r.pb_key_control IS NOT NULL THEN RAISE EXCEPTION 'periodic source reservation missing' USING ERRCODE='23514'; END IF;RETURN;END IF;
 SELECT * INTO s FROM settlements WHERE request_id=r.id;
 IF v.status IN ('reserved','pending_reconciliation') THEN
  IF s.id IS NOT NULL THEN RAISE EXCEPTION 'periodic pending source already settled' USING ERRCODE='23514'; END IF;
  expected_h:=v.amount;expected_s:=0;expected_state:='held';
 ELSE
  IF s.id IS NULL OR s.status IS DISTINCT FROM v.status THEN RAISE EXCEPTION 'periodic terminal source settlement missing' USING ERRCODE='23514'; END IF;
  expected_h:=0;expected_s:=s.charged_amount;expected_state:=s.status;
 END IF;
 FOR c IN SELECT * FROM periodic_budget_controls WHERE (scope='tenant' AND tenant_id=r.tenant_id)
    OR (scope='key' AND tenant_id=r.tenant_id AND key_id=r.key_id) LOOP
  marker:=CASE c.scope WHEN 'tenant' THEN r.pb_tenant_control ELSE r.pb_key_control END;
  SELECT * INTO a FROM periodic_budget_allocations WHERE control_id=c.id AND subject_type='customer_request' AND subject_id=r.id;
  IF NOT FOUND THEN
   IF marker=c.id OR v.status IN ('reserved','pending_reconciliation') THEN
    RAISE EXCEPTION 'periodic customer allocation missing' USING ERRCODE='23514'; END IF;
  ELSE
   IF a.revision<=0 OR a.last_event_id IS NULL OR (a.held_amount,a.spent_amount,a.source_held,a.source_spent,a.state,a.upper_amount)
    IS DISTINCT FROM (expected_h,expected_s,expected_h,expected_s,expected_state,v.amount) THEN
    RAISE EXCEPTION 'periodic customer projection/source mismatch' USING ERRCODE='23514'; END IF;
   IF (marker=c.id AND a.origin<>'new') OR (marker IS NULL AND a.origin='new') THEN
    RAISE EXCEPTION 'periodic customer origin mismatch' USING ERRCODE='23514'; END IF;
  END IF;
 END LOOP;
END

DECLARE p procurement_reservations%ROWTYPE;c periodic_budget_controls%ROWTYPE;a periodic_budget_allocations%ROWTYPE;expected_state text;
BEGIN
 SELECT * INTO p FROM procurement_reservations WHERE attempt_id=subject;IF NOT FOUND THEN RETURN; END IF;
 SELECT * INTO c FROM periodic_budget_controls WHERE scope='procurement' AND account_id=p.account_id;IF NOT FOUND THEN RETURN;END IF;
 SELECT * INTO a FROM periodic_budget_allocations WHERE control_id=c.id AND subject_type='supplier_attempt' AND subject_id=subject;
 IF NOT FOUND THEN
  IF p.pb_control=c.id OR p.state IN ('prepared','sending','unknown','disputed') OR EXISTS
   (SELECT 1 FROM procurement_budget_events WHERE attempt_id=p.attempt_id AND pb_created_xid=pg_current_xact_id()) THEN
   RAISE EXCEPTION 'periodic supplier allocation missing' USING ERRCODE='23514'; END IF;RETURN;
 END IF;
 expected_state:=CASE p.state WHEN 'settled' THEN 'settled' WHEN 'released' THEN 'released' WHEN 'disputed' THEN 'disputed' ELSE 'held' END;
 IF a.revision<=0 OR a.last_event_id IS NULL OR (a.held_amount,a.spent_amount,a.source_held,a.source_spent,a.state,a.upper_amount)
  IS DISTINCT FROM (p.held_amount,greatest(p.spent_amount-a.baseline,0),p.held_amount,p.spent_amount,expected_state,p.upper_amount::bigint) THEN
  RAISE EXCEPTION 'periodic supplier projection/source mismatch' USING ERRCODE='23514'; END IF;
 IF (p.pb_control=c.id AND a.origin<>'new') OR (p.pb_control IS NULL AND a.origin='new') THEN
  RAISE EXCEPTION 'periodic supplier origin mismatch' USING ERRCODE='23514'; END IF;
END

BEGIN
 IF value IS NULL OR value !~ '^[1-9][0-9]{0,18}$' THEN RETURN false; END IF;
 RETURN value::NUMERIC<=9223372036854775807;
END

DECLARE full_xid numeric;
BEGIN
 IF stamp IS DISTINCT FROM pg_current_xact_id() OR tuple_xid IS NULL THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM pg_locks WHERE locktype='transactionid' AND transactionid=tuple_xid
   AND pid=pg_backend_pid() AND granted AND mode='ExclusiveLock') THEN RETURN true; END IF;
 full_xid:=floor(stamp::text::numeric/4294967296)*4294967296+tuple_xid::text::numeric;
 IF full_xid<stamp::text::numeric THEN full_xid:=full_xid+4294967296; END IF;
 IF full_xid<=stamp::text::numeric THEN RETURN false; END IF;
 BEGIN RETURN pg_xact_status(full_xid::text::xid8) IS NOT DISTINCT FROM 'in progress';
 EXCEPTION WHEN invalid_parameter_value THEN RETURN false; END;
END

DECLARE at_time timestamptz:=clock_timestamp();delay_seconds integer;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'immutable mock delivery';END IF;
 IF TG_OP='INSERT' THEN IF NEW.state<>'pending' OR NEW.generation<>0 OR NEW.attempt_count<>0 OR NEW.lease_until IS NOT NULL OR NEW.last_error_code IS NOT NULL OR NEW.delivered_at IS NOT NULL THEN RAISE EXCEPTION 'mock delivery initial state';END IF;RETURN NEW;END IF;
 IF (NEW.event_id,NEW.created_at) IS DISTINCT FROM (OLD.event_id,OLD.created_at) OR OLD.state IN ('delivered','review_required') THEN RAISE EXCEPTION 'mock delivery immutable terminal';END IF;
 IF NEW.state='leased' AND NEW.generation=OLD.generation+1 AND NEW.attempt_count=OLD.attempt_count+1 AND OLD.attempt_count<20 AND
  ((OLD.state IN ('pending','retry_wait') AND OLD.next_attempt_at<=at_time) OR (OLD.state='leased' AND OLD.lease_until<=at_time)) THEN
  NEW.lease_until:=at_time+interval '60 seconds';NEW.last_error_code:=NULL;NEW.delivered_at:=NULL;NEW.next_attempt_at:=OLD.next_attempt_at;RETURN NEW;END IF;
 IF OLD.state<>'leased' OR NEW.generation<>OLD.generation OR NEW.attempt_count<>OLD.attempt_count THEN RAISE EXCEPTION 'mock delivery stale transition';END IF;
 NEW.lease_until:=NULL;
 IF NEW.state='delivered' AND at_time<OLD.lease_until THEN NEW.delivered_at:=at_time;NEW.last_error_code:=NULL;NEW.next_attempt_at:=OLD.next_attempt_at;RETURN NEW;END IF;
 IF NEW.state='retry_wait' AND at_time<OLD.lease_until AND OLD.attempt_count<20 AND NEW.last_error_code IN ('network','timeout','auth','protocol','environment','temporary','permanent') THEN
  delay_seconds:=CASE OLD.attempt_count WHEN 1 THEN 1 WHEN 2 THEN 5 WHEN 3 THEN 30 WHEN 4 THEN 120 ELSE 300 END;
  NEW.next_attempt_at:=at_time+make_interval(secs=>delay_seconds);NEW.delivered_at:=NULL;RETURN NEW;END IF;
 IF NEW.state='review_required' AND OLD.attempt_count=20 AND NEW.last_error_code='attempts_exhausted' AND
  (OLD.lease_until<=at_time OR EXISTS(SELECT 1 FROM mock_delivery_observations x WHERE x.event_id=OLD.event_id AND x.generation=OLD.generation AND x.outcome='failed')) THEN
  NEW.delivered_at:=NULL;NEW.next_attempt_at:=OLD.next_attempt_at;RETURN NEW;END IF;
 RAISE EXCEPTION 'mock delivery transition';
END

 BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'immutable mock fault';END IF;
 IF TG_OP='INSERT' THEN IF NEW.remaining<>1 OR NEW.consumed_at IS NOT NULL THEN RAISE EXCEPTION 'mock fault initial state';END IF;RETURN NEW;END IF;
 IF (NEW.control_operation_id,NEW.boundary,NEW.target_kind,NEW.target_id,NEW.created_at) IS DISTINCT FROM (OLD.control_operation_id,OLD.boundary,OLD.target_kind,OLD.target_id,OLD.created_at) OR OLD.remaining<>1 OR NEW.remaining<>0 OR NEW.consumed_at IS NULL THEN RAISE EXCEPTION 'mock fault transition';END IF;RETURN NEW;
END

DECLARE oid text;cid text;eid text;capid text;controlid text;p mock_command_processing%ROWTYPE;f mock_fault_plans%ROWTYPE;q mock_controls%ROWTYPE;
BEGIN
 CASE TG_TABLE_NAME
 WHEN 'mock_orders' THEN oid:=NEW.merchant_order_id;
 WHEN 'mock_order_transitions' THEN oid:=NEW.merchant_order_id;cid:=NEW.command_id;controlid:=NEW.control_operation_id;
 WHEN 'mock_captures' THEN oid:=NEW.merchant_order_id;capid:=NEW.id;controlid:=NEW.control_operation_id;
 WHEN 'mock_commands','mock_command_results' THEN cid:=NEW.command_id;
 WHEN 'mock_command_processing' THEN
  cid:=NEW.command_id;SELECT * INTO p FROM mock_command_processing WHERE command_id=cid;
  IF p.held_by_control_id IS NOT NULL THEN SELECT * INTO f FROM mock_fault_plans WHERE control_operation_id=p.held_by_control_id;
   IF f.target_kind<>'command' OR f.target_id<>cid OR f.boundary<>(CASE (SELECT kind FROM mock_commands WHERE command_id=cid) WHEN 'checkout' THEN 'hold_checkout_before_effect' ELSE 'hold_cancel_before_effect' END) OR f.remaining<>0 THEN RAISE EXCEPTION 'mock held command evidence';END IF;END IF;
  IF p.released_by_control_id IS NOT NULL THEN SELECT * INTO q FROM mock_controls WHERE operation_id=p.released_by_control_id;IF q.action<>'release_command' OR q.target_reference<>cid OR NOT mock_control_complete(q.operation_id) THEN RAISE EXCEPTION 'mock release evidence';END IF;END IF;
 WHEN 'mock_notification_events' THEN
  eid:=NEW.id;controlid:=NEW.control_operation_id;capid:=NEW.canonical_capture_id;SELECT * INTO q FROM mock_controls WHERE operation_id=controlid;
  IF (capid IS NULL AND q.action<>'emit_test_event') OR (capid IS NOT NULL AND q.action<>'capture_order') THEN RAISE EXCEPTION 'mock event control evidence';END IF;
 WHEN 'mock_notification_delivery','mock_delivery_attempts','mock_delivery_observations' THEN eid:=NEW.event_id;
 WHEN 'mock_controls' THEN controlid:=NEW.operation_id;
 WHEN 'mock_fault_plans' THEN controlid:=NEW.control_operation_id;
 END CASE;
 IF oid IS NOT NULL AND NOT coalesce(mock_order_complete(oid),false) THEN RAISE EXCEPTION 'mock order facts incomplete';END IF;
 IF cid IS NOT NULL AND NOT coalesce(mock_command_complete(cid),false) THEN RAISE EXCEPTION 'mock command facts incomplete';END IF;
 IF capid IS NOT NULL AND NOT coalesce(mock_capture_complete(capid),false) THEN RAISE EXCEPTION 'mock capture facts incomplete';END IF;
 IF eid IS NOT NULL AND NOT coalesce(mock_delivery_complete(eid),false) THEN RAISE EXCEPTION 'mock notification facts incomplete';END IF;
 IF controlid IS NOT NULL AND NOT coalesce(mock_control_complete(controlid),false) THEN RAISE EXCEPTION 'mock control facts incomplete';END IF;RETURN NULL;
END

DECLARE j jsonb;e mock_environment%ROWTYPE;required text[];c mock_commands%ROWTYPE;processing mock_command_processing%ROWTYPE;r mock_command_results%ROWTYPE;o mock_orders%ROWTYPE;cap mock_captures%ROWTYPE;d mock_notification_delivery%ROWTYPE;k mock_signing_keys%ROWTYPE;n mock_notification_events%ROWTYPE;
BEGIN
 SELECT * INTO e FROM mock_environment WHERE singleton;IF e.environment_id IS NULL THEN RAISE EXCEPTION 'mock environment missing';END IF;
 IF TG_TABLE_NAME='mock_commands' THEN
  j:=mock_json(NEW.canonical_parameters);required:=ARRAY['schema_version','environment_id','merchant_id','command_id','merchant_order_id'];IF NEW.kind='checkout' THEN required:=required||ARRAY['amount','currency','created_at','expires_at'];END IF;
  IF NOT mock_fields(j,required) OR NOT mock_strings(j,array_remove(required,'schema_version')) OR j->'schema_version'<>'1'::jsonb OR j->>'environment_id'<>e.environment_id OR j->>'merchant_id'<>e.merchant_id OR j->>'command_id'<>NEW.command_id OR j->>'merchant_order_id'<>NEW.merchant_order_id OR substr(NEW.merchant_order_id,6,36)<>e.environment_id THEN RAISE EXCEPTION 'mock command binding';END IF;
  IF NEW.kind='checkout' AND (NOT coalesce(mock_positive(j->>'amount'),false) OR j->>'currency'<>'CNY' OR NOT coalesce(mock_time(j->>'created_at'),false) OR NOT coalesce(mock_time(j->>'expires_at'),false) OR (j->>'expires_at')::timestamptz<>(j->>'created_at')::timestamptz+interval '900 seconds') THEN RAISE EXCEPTION 'mock checkout terms';END IF;
 ELSIF TG_TABLE_NAME='mock_queries' THEN
  j:=mock_json(NEW.canonical_parameters);IF NOT mock_fields(j,ARRAY['schema_version','environment_id','merchant_id','query_id','command_id','merchant_order_id','command_kind','parameter_digest']) OR NOT mock_strings(j,ARRAY['environment_id','merchant_id','query_id','command_id','merchant_order_id','command_kind','parameter_digest']) OR j->'schema_version'<>'1'::jsonb OR j->>'environment_id'<>e.environment_id OR j->>'merchant_id'<>e.merchant_id OR j->>'query_id'<>NEW.query_id OR j->>'command_id'<>NEW.command_id OR j->>'merchant_order_id'<>NEW.merchant_order_id OR j->>'command_kind'<>NEW.command_kind OR j->>'parameter_digest'<>NEW.expected_parameter_digest THEN RAISE EXCEPTION 'mock query binding';END IF;
  j:=mock_json(NEW.snapshot_body);IF NOT coalesce(mock_reply_valid(j,true),false) OR j->>'query_id'<>NEW.query_id OR j->>'command_id'<>NEW.command_id OR j->>'merchant_order_id'<>NEW.merchant_order_id OR j->>'command_kind'<>NEW.command_kind OR j->>'parameter_digest'<>NEW.expected_parameter_digest THEN RAISE EXCEPTION 'mock query snapshot binding';END IF;
  SELECT * INTO c FROM mock_commands WHERE command_id=NEW.command_id;
  IF c.command_id IS NULL THEN IF j->>'command_state'<>'not_seen' THEN RAISE EXCEPTION 'mock unseen query state';END IF;RETURN NEW;END IF;
  IF (c.merchant_order_id,c.kind,c.parameter_digest) IS DISTINCT FROM (NEW.merchant_order_id,NEW.command_kind,NEW.expected_parameter_digest) THEN RAISE EXCEPTION 'mock query parameter conflict';END IF;
  SELECT * INTO processing FROM mock_command_processing WHERE command_id=c.command_id;
  IF processing.state='held' THEN IF j->>'command_state'<>'in_progress' THEN RAISE EXCEPTION 'mock held query state';END IF;RETURN NEW;END IF;
  SELECT * INTO r FROM mock_command_results WHERE command_id=c.command_id;SELECT * INTO o FROM mock_orders WHERE merchant_order_id=c.merchant_order_id;
  IF r.command_id IS NULL OR j->>'command_state'<>'completed' THEN RAISE EXCEPTION 'mock completed query state';END IF;
  IF o.state='captured' THEN SELECT * INTO cap FROM mock_captures WHERE merchant_order_id=o.merchant_order_id;
   IF j->'result'->>'status'<>'captured' OR j->>'provider_order_revision'<>o.revision::text OR j->'result'->'capture'->>'provider_transaction_id'<>cap.provider_transaction_id OR j->'result'->'capture'->>'amount'<>cap.amount::text OR (j->'result'->'capture'->>'occurred_at')::timestamptz<>cap.occurred_at THEN RAISE EXCEPTION 'mock query capture snapshot';END IF;
  ELSIF o.state='closed' THEN IF j->'result'->>'status'<>'closed' OR j->>'provider_order_revision'<>o.revision::text OR (j->'result'->>'closed_at')::timestamptz<>o.closed_at THEN RAISE EXCEPTION 'mock query closed snapshot';END IF;
  ELSE IF j->'result'<>mock_json(r.result_body)->'result' OR j->>'provider_order_revision'<>r.provider_order_revision::text THEN RAISE EXCEPTION 'mock query final snapshot';END IF;END IF;
 ELSIF TG_TABLE_NAME='mock_notification_events' THEN
  j:=mock_json(NEW.canonical_body);required:=ARRAY['schema_version','event_id','event_type','environment_id','merchant_id','order_id','provider_transaction_id','amount','currency','occurred_at','provider_order_revision'];
  CASE NEW.event_type WHEN 'checkout.failed' THEN required:=required||ARRAY['failure_code'];WHEN 'refund.confirmed','refund.failed' THEN required:=required||ARRAY['refund_id'];WHEN 'dispute.opened','chargeback.debited','chargeback.reversed' THEN required:=required||ARRAY['case_id'];ELSE NULL;END CASE;
  IF NOT mock_fields(j,required) OR NOT mock_strings(j,array_remove(array_remove(required,'schema_version'),'provider_transaction_id')) OR j->'schema_version'<>'1'::jsonb OR j->>'environment_id'<>e.environment_id OR j->>'merchant_id'<>e.merchant_id OR j->>'event_id'<>NEW.event_id OR j->>'event_type'<>NEW.event_type OR NEW.merchant_order_id<>'mps1.'||e.environment_id||'.'||(j->>'order_id') OR NOT coalesce(mock_positive(j->>'amount'),false) OR j->>'currency'<>'CNY' OR NOT coalesce(mock_time(j->>'occurred_at'),false) OR NOT coalesce(mock_positive(j->>'provider_order_revision'),false) THEN RAISE EXCEPTION 'mock notification binding';END IF;
  IF (NEW.event_type='checkout.failed' AND (j->'provider_transaction_id'<>'null'::jsonb OR j->>'failure_code' NOT IN ('checkout_rejected','order_closed','order_expired'))) OR (NEW.event_type<>'checkout.failed' AND (NOT mock_strings(j,ARRAY['provider_transaction_id']) OR NOT coalesce(mock_ref(j->>'provider_transaction_id'),false))) OR (NEW.event_type IN ('refund.confirmed','refund.failed') AND NOT coalesce(mock_uuid(j->>'refund_id'),false)) OR (NEW.event_type IN ('dispute.opened','chargeback.debited','chargeback.reversed') AND NOT coalesce(mock_ref(j->>'case_id'),false)) THEN RAISE EXCEPTION 'mock notification union';END IF;
 ELSIF TG_TABLE_NAME='mock_delivery_attempts' THEN
  SELECT * INTO d FROM mock_notification_delivery WHERE event_id=NEW.event_id;SELECT * INTO n FROM mock_notification_events WHERE id=NEW.event_id;SELECT * INTO k FROM mock_signing_keys WHERE key_id=NEW.signing_key_id;
  IF d.event_id IS NULL OR n.id IS NULL OR k.key_id IS NULL OR d.state<>'leased' OR (d.generation,d.attempt_count,d.lease_until) IS DISTINCT FROM (NEW.generation,NEW.attempt_no,NEW.lease_until) OR NEW.body_digest<>n.business_digest OR NEW.delivery_time<>floor(extract(epoch FROM NEW.claimed_at))::bigint OR to_timestamp(NEW.delivery_time)<k.not_before OR to_timestamp(NEW.delivery_time)>k.not_after THEN RAISE EXCEPTION 'mock delivery attempt binding';END IF;
 ELSIF TG_TABLE_NAME='mock_delivery_observations' THEN
  SELECT * INTO n FROM mock_notification_events WHERE id=NEW.event_id;
  IF n.id IS NULL THEN RAISE EXCEPTION 'mock observation event missing';END IF;
  NEW.observed_at:=clock_timestamp();
  IF NEW.outcome='ack' THEN
   j:=mock_json(NEW.receipt_data);
   IF NOT mock_fields(j,ARRAY['receipt_id','event_id','status','environment','received_at']) OR NOT mock_strings(j,ARRAY['receipt_id','event_id','status','environment','received_at']) OR NOT coalesce(mock_uuid(j->>'receipt_id'),false) OR j->>'event_id'<>n.event_id OR j->>'status'<>'received' OR j->>'environment'<>'sandbox' OR NOT coalesce(mock_time(j->>'received_at'),false) OR (j->>'received_at')::timestamptz>NEW.observed_at+interval '5 seconds' THEN RAISE EXCEPTION 'mock ACK receipt binding';END IF;
  END IF;
 ELSIF TG_TABLE_NAME='mock_controls' THEN
  j:=mock_json(NEW.canonical_parameters);IF NOT mock_fields(j,ARRAY['operation_id','action','scenario','merchant_order_id','command_id','query_id','event_id']) OR NOT mock_strings(j,ARRAY['operation_id','action','scenario']) OR j->>'operation_id'<>NEW.operation_id OR j->>'action'<>NEW.action OR j->>'scenario'<>NEW.scenario THEN RAISE EXCEPTION 'mock control binding';END IF;
  IF NEW.action IN ('capture_order','emit_test_event') THEN IF NOT mock_strings(j,ARRAY['merchant_order_id']) OR j->>'merchant_order_id'<>NEW.target_reference OR NOT mock_merchant_order(NEW.target_reference) OR j->'command_id'<>'null'::jsonb OR j->'query_id'<>'null'::jsonb OR j->'event_id'<>'null'::jsonb THEN RAISE EXCEPTION 'mock control target';END IF;
  ELSIF NEW.action='release_command' THEN IF NOT mock_strings(j,ARRAY['command_id']) OR j->>'command_id'<>NEW.target_reference OR NOT mock_uuid(NEW.target_reference) OR j->'merchant_order_id'<>'null'::jsonb OR j->'query_id'<>'null'::jsonb OR j->'event_id'<>'null'::jsonb THEN RAISE EXCEPTION 'mock release target';END IF;
  ELSE IF j->'merchant_order_id'<>'null'::jsonb OR NOT coalesce(((j->>'command_id'=NEW.target_reference AND mock_uuid(NEW.target_reference) AND j->'query_id'='null'::jsonb AND j->'event_id'='null'::jsonb) OR (j->>'query_id'=NEW.target_reference AND mock_uuid(NEW.target_reference) AND j->'command_id'='null'::jsonb AND j->'event_id'='null'::jsonb) OR (j->>'event_id'=NEW.target_reference AND mock_ref(NEW.target_reference) AND j->'command_id'='null'::jsonb AND j->'query_id'='null'::jsonb)),false) THEN RAISE EXCEPTION 'mock fault target';END IF;END IF;
  IF NEW.action='arm_fault' AND ((NEW.scenario='after_query_snapshot_commit_drop_reply_once' AND NOT mock_strings(j,ARRAY['query_id'])) OR (NEW.scenario='before_callback_send_once' AND NOT mock_strings(j,ARRAY['event_id'])) OR (NEW.scenario NOT IN ('after_query_snapshot_commit_drop_reply_once','before_callback_send_once') AND NOT mock_strings(j,ARRAY['command_id']))) THEN RAISE EXCEPTION 'mock fault scenario target';END IF;
 END IF;RETURN NEW;
END

 BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'immutable mock order';END IF;
 IF TG_OP='INSERT' THEN IF NEW.state NOT IN ('ready','closed') THEN RAISE EXCEPTION 'mock order initial state';END IF;NEW.revision:=1;RETURN NEW;END IF;
 IF (NEW.merchant_order_id,NEW.order_id,NEW.environment_id,NEW.merchant_id,NEW.amount,NEW.currency,NEW.created_at,NEW.expires_at,NEW.checkout_ref,NEW.created_locally_at) IS DISTINCT FROM (OLD.merchant_order_id,OLD.order_id,OLD.environment_id,OLD.merchant_id,OLD.amount,OLD.currency,OLD.created_at,OLD.expires_at,OLD.checkout_ref,OLD.created_locally_at) THEN RAISE EXCEPTION 'immutable mock order terms';END IF;
 IF NEW.state=OLD.state THEN IF NEW.closed_at IS DISTINCT FROM OLD.closed_at THEN RAISE EXCEPTION 'immutable mock close';END IF;NEW.revision:=OLD.revision;RETURN NEW;END IF;
 IF OLD.state<>'ready' OR NEW.state NOT IN ('closed','captured') THEN RAISE EXCEPTION 'mock order transition';END IF;NEW.revision:=OLD.revision+1;RETURN NEW;
END

 BEGIN
 IF current_user<>(SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid=TG_RELID) THEN RAISE EXCEPTION 'mock owner required';END IF;IF TG_TABLE_NAME='mock_signing_keys' AND (SELECT count(*) FROM mock_signing_keys)>=128 THEN RAISE EXCEPTION 'mock signing key limit';END IF;RETURN NEW;
END

 BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'immutable mock processing';END IF;
 IF TG_OP='INSERT' THEN RETURN NEW;END IF;
 IF OLD.state<>'held' OR NEW.state<>'completed' OR (NEW.command_id,NEW.held_by_control_id,NEW.created_at) IS DISTINCT FROM (OLD.command_id,OLD.held_by_control_id,OLD.created_at) OR NEW.released_by_control_id IS NULL THEN RAISE EXCEPTION 'mock processing transition';END IF;RETURN NEW;
END

DECLARE expected text[]; e mock_environment%ROWTYPE;
BEGIN
 expected:=ARRAY['schema_version','environment_id','merchant_id','merchant_order_id','command_id','command_kind','parameter_digest','command_state','provider_order_revision','result'];
 IF is_query THEN expected:=expected||ARRAY['query_id'];END IF;
 SELECT * INTO e FROM mock_environment WHERE singleton;
 IF e.environment_id IS NULL OR NOT mock_fields(j,expected) OR NOT mock_strings(j,ARRAY['environment_id','merchant_id','merchant_order_id','command_id','command_kind','parameter_digest','command_state']) OR (is_query AND NOT mock_strings(j,ARRAY['query_id'])) OR j->'schema_version'<>'1'::jsonb OR j->>'environment_id'<>e.environment_id OR j->>'merchant_id'<>e.merchant_id
  OR NOT mock_merchant_order(j->>'merchant_order_id') OR substr(j->>'merchant_order_id',6,36)<>e.environment_id OR NOT mock_uuid(j->>'command_id') OR j->>'command_kind' NOT IN ('checkout','cancel') OR j->>'parameter_digest' !~ '^[0-9a-f]{64}$'
  OR (is_query AND NOT mock_uuid(j->>'query_id')) THEN RETURN false;END IF;
 IF j->>'command_state'='in_progress' OR (is_query AND j->>'command_state'='not_seen') THEN RETURN j->'result'='null'::jsonb AND j->'provider_order_revision'='null'::jsonb;END IF;
 RETURN j->>'command_state'='completed' AND mock_strings(j,ARRAY['provider_order_revision']) AND coalesce(mock_result_valid(j->'result',j->>'command_kind',j->>'provider_order_revision'),false);
END

DECLARE c jsonb;
BEGIN
 IF NOT mock_fields(j,ARRAY['status','checkout_ref','failure_code','capture','closed_at']) OR NOT mock_strings(j,ARRAY['status']) OR NOT coalesce(mock_positive(revision),false) THEN RETURN false;END IF;
 IF kind='cancel' AND j->>'status' NOT IN ('closed','captured') THEN RETURN false;END IF;
 CASE j->>'status'
 WHEN 'ready' THEN RETURN mock_strings(j,ARRAY['checkout_ref']) AND j->>'checkout_ref' ~ '^checkout:[0-9a-f-]{36}$' AND mock_uuid(substr(j->>'checkout_ref',10)) AND j->'failure_code'='null'::jsonb AND j->'capture'='null'::jsonb AND j->'closed_at'='null'::jsonb;
 WHEN 'rejected' THEN RETURN mock_strings(j,ARRAY['failure_code']) AND j->'checkout_ref'='null'::jsonb AND j->>'failure_code' IN ('checkout_rejected','order_closed','order_expired') AND j->'capture'='null'::jsonb AND j->'closed_at'='null'::jsonb;
 WHEN 'closed' THEN RETURN j->'checkout_ref'='null'::jsonb AND j->'failure_code'='null'::jsonb AND j->'capture'='null'::jsonb AND coalesce(mock_time(j->>'closed_at'),false);
 WHEN 'captured' THEN
  c:=j->'capture';RETURN j->'checkout_ref'='null'::jsonb AND j->'failure_code'='null'::jsonb AND j->'closed_at'='null'::jsonb
   AND mock_fields(c,ARRAY['provider_transaction_id','amount','currency','occurred_at','provider_order_revision']) AND mock_strings(c,ARRAY['provider_transaction_id','amount','currency','occurred_at','provider_order_revision']) AND mock_ref(c->>'provider_transaction_id') AND mock_positive(c->>'amount') AND c->>'currency'='CNY' AND mock_time(c->>'occurred_at') AND c->>'provider_order_revision'=revision;
 ELSE RETURN false;END CASE;
END

DECLARE c mock_controls%ROWTYPE;j jsonb; resource text;
BEGIN
 SELECT * INTO c FROM mock_controls WHERE operation_id=cid;IF c.operation_id IS NULL THEN RETURN false;END IF;j:=mock_json(c.result_body);resource:=j->>'resource_id';
 IF NOT mock_fields(j,ARRAY['operation_id','status','reason','resource_id']) OR NOT mock_strings(j,ARRAY['operation_id','status','reason']) OR j->>'operation_id'<>c.operation_id THEN RETURN false;END IF;
 IF j->>'status'='rejected' THEN RETURN j->>'reason' IN ('state_conflict','target_not_found') AND j->'resource_id'='null'::jsonb AND
  NOT EXISTS(SELECT 1 FROM mock_captures WHERE control_operation_id=cid) AND NOT EXISTS(SELECT 1 FROM mock_notification_events WHERE control_operation_id=cid) AND NOT EXISTS(SELECT 1 FROM mock_fault_plans WHERE control_operation_id=cid) AND NOT EXISTS(SELECT 1 FROM mock_command_processing WHERE released_by_control_id=cid);END IF;
 IF j->>'status'<>'accepted' OR j->>'reason'<>'accepted' OR NOT coalesce(mock_uuid(resource),false) THEN RETURN false;END IF;
 CASE c.action
 WHEN 'capture_order' THEN RETURN EXISTS(SELECT 1 FROM mock_captures x WHERE x.id=resource AND x.merchant_order_id=c.target_reference);
 WHEN 'emit_test_event' THEN RETURN EXISTS(SELECT 1 FROM mock_notification_events x WHERE x.id=resource AND x.control_operation_id=cid AND x.merchant_order_id=c.target_reference AND x.canonical_capture_id IS NULL);
 WHEN 'release_command' THEN RETURN resource=c.target_reference AND EXISTS(SELECT 1 FROM mock_command_processing x WHERE x.command_id=resource AND x.state='completed' AND x.released_by_control_id=cid);
 WHEN 'arm_fault' THEN RETURN resource=cid AND EXISTS(SELECT 1 FROM mock_fault_plans x WHERE x.control_operation_id=cid AND x.boundary=c.scenario AND x.target_id=c.target_reference);
 ELSE RETURN false;END CASE;
END

DECLARE t timestamptz;
BEGIN
 IF v !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$' OR left(v,4)='0000' THEN RETURN false;END IF;
 BEGIN t:=v::timestamptz; EXCEPTION WHEN OTHERS THEN RETURN false;END;
 RETURN to_char(t AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')=v;
END

DECLARE ref text;
BEGIN
 IF TG_TABLE_NAME='receiver_inbox' THEN ref:=NEW.id;ELSE ref:=NEW.inbox_id;END IF;
 IF NOT EXISTS(SELECT 1 FROM receiver_inbox i JOIN receiver_receipts r ON r.inbox_id=i.id WHERE i.id=ref) THEN RAISE EXCEPTION 'receiver inbox receipt incomplete';END IF;RETURN NULL;
END

DECLARE j jsonb;e receiver_environment%ROWTYPE;i receiver_inbox%ROWTYPE;k receiver_signing_keys%ROWTYPE;observed timestamptz;
BEGIN
 SELECT * INTO e FROM receiver_environment WHERE singleton;IF e.environment_id IS NULL THEN RAISE EXCEPTION 'receiver environment missing';END IF;
 IF TG_TABLE_NAME='receiver_inbox' THEN
  j:=receiver_json(NEW.canonical_body);
  IF NOT receiver_strings(j,ARRAY['environment_id','merchant_id','event_id','event_type','order_id','amount','currency','occurred_at','provider_order_revision']) OR j->'schema_version' IS DISTINCT FROM '1'::jsonb OR j->>'environment_id'<>NEW.environment_id OR j->>'merchant_id'<>NEW.merchant_id OR j->>'event_id'<>NEW.event_id OR NOT receiver_uuid(j->>'order_id') THEN RAISE EXCEPTION 'receiver event binding';END IF;
  NEW.verified_at:=transaction_timestamp();SELECT * INTO k FROM receiver_signing_keys WHERE key_id=NEW.signing_key_id;observed:=NEW.verified_at;
 ELSIF TG_TABLE_NAME='receiver_receipts' THEN
  SELECT * INTO i FROM receiver_inbox WHERE id=NEW.inbox_id;j:=receiver_json(NEW.receipt_data);
  IF i.id IS NULL OR NOT receiver_fields(j,ARRAY['receipt_id','event_id','status','environment','received_at']) OR NOT receiver_strings(j,ARRAY['receipt_id','event_id','status','environment','received_at']) OR j->>'receipt_id'<>NEW.receipt_id OR j->>'event_id'<>i.event_id OR j->>'status'<>'received' OR j->>'environment'<>'sandbox' OR j->>'received_at'<>to_char(NEW.received_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') THEN RAISE EXCEPTION 'receiver receipt binding';END IF;
  IF NEW.received_at<i.verified_at OR NEW.received_at>clock_timestamp()+interval '5 seconds' THEN RAISE EXCEPTION 'receiver receipt time';END IF;RETURN NEW;
 ELSIF TG_TABLE_NAME='receiver_conflicts' THEN
  SELECT * INTO i FROM receiver_inbox WHERE id=NEW.inbox_id;
  IF i.id IS NULL OR NEW.observed_digest=i.business_digest THEN RAISE EXCEPTION 'receiver conflict binding';END IF;
  NEW.observed_at:=transaction_timestamp();SELECT * INTO k FROM receiver_signing_keys WHERE key_id=NEW.signing_key_id;observed:=NEW.observed_at;
 END IF;
 IF k.key_id IS NULL OR to_timestamp(NEW.delivery_time)<k.not_before OR to_timestamp(NEW.delivery_time)>k.not_after OR abs(extract(epoch FROM observed)-NEW.delivery_time)>300 THEN RAISE EXCEPTION 'receiver signing window';END IF;RETURN NEW;
END

 BEGIN
 IF current_user<>(SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid=TG_RELID) THEN RAISE EXCEPTION 'receiver owner required';END IF;
 IF TG_TABLE_NAME='receiver_signing_keys' AND (SELECT count(*) FROM receiver_signing_keys)>=128 THEN RAISE EXCEPTION 'receiver signing key limit';END IF;RETURN NEW;
END
